"use client"

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"
import { StatCard } from "../stat-card"
import { CompanyCard } from "../company-card"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { CheckCircle2, Plus, FileText, TrendingUp, ArrowUpRight } from "lucide-react"
import { fetchDashboardStats, fetchCompanies, fetchRecentTransactions, createTransaction, fetchLeafCategories } from "@/lib/api"
import { type TransactionPayload } from "@/lib/api-enhanced"
import { useState } from "react"
import { toast } from "sonner"

interface DashboardOverviewProps {
  onNavigate: (tab: string) => void
}

export function DashboardOverview({ onNavigate }: DashboardOverviewProps) {
  const queryClient = useQueryClient()
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false)

  const { data: stats, isLoading: statsLoading } = useQuery({
    queryKey: ["dashboard-stats"],
    queryFn: fetchDashboardStats,
  })

  const { data: companies, isLoading: companiesLoading } = useQuery({
    queryKey: ["companies"],
    queryFn: fetchCompanies,
  })

  const { data: transactions, isLoading: transactionsLoading } = useQuery({
    queryKey: ["recent-transactions"],
    queryFn: fetchRecentTransactions,
  })

  const { data: categories } = useQuery({
    queryKey: ["leaf-categories"],
    queryFn: fetchLeafCategories,
  })

  const createTransactionMutation = useMutation({
    mutationFn: createTransaction,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["recent-transactions"] })
      queryClient.invalidateQueries({ queryKey: ["dashboard-stats"] })
      setIsCreateDialogOpen(false)
      toast.success("Transaction created successfully!")
    },
    onError: (error: any) => {
      toast.error(error.message || "Failed to create transaction")
    },
  })

  if (statsLoading || companiesLoading || transactionsLoading) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        Loading dashboard data...
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <Alert className="bg-emerald-50 dark:bg-emerald-950/20 border-emerald-200 dark:border-emerald-800">
        <CheckCircle2 className="h-4 w-4 text-emerald-600" />
        <AlertDescription className="text-emerald-700 dark:text-emerald-400">
          <strong>All companies updated today</strong> — Last update: 4:32 PM | Data refreshes every 5 minutes
        </AlertDescription>
      </Alert>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          label="Total Group Cash"
          value={stats?.totalCash || "RWF 1,250,000,000"}
          change="+3.2% from yesterday"
          changeType="positive"
          variant="cash"
        />
        <StatCard
          label="Total Daily Revenue"
          value={stats?.dailyRevenue || "RWF 85,000,000"}
          change="+12.5% from yesterday"
          changeType="positive"
          variant="revenue"
        />
        <StatCard
          label="Total Daily Expenses"
          value={stats?.dailyExpenses || "RWF 61,000,000"}
          change="+8.2% from yesterday"
          changeType="negative"
          variant="expense"
        />
        <StatCard
          label="Net Daily Profit"
          value={stats?.netProfit || "RWF 24,000,000"}
          change="+21.3% from yesterday"
          changeType="positive"
          variant="profit"
        />
      </div>

      <Card className="shadow-xl border-border/40 bg-gradient-to-br from-slate-50 to-white dark:from-slate-900 dark:to-slate-800">
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-2xl font-serif tracking-tight">Quick Actions</CardTitle>
            <p className="text-sm text-muted-foreground mt-1">Manage your business operations</p>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
              <DialogTrigger asChild>
                <Button className="h-24 flex-col gap-2 bg-gradient-to-br from-blue-500 to-blue-600 hover:from-blue-600 hover:to-blue-700">
                  <Plus className="h-6 w-6" />
                  <span>Create Transaction</span>
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle className="text-2xl font-serif">Create New Transaction</DialogTitle>
                  <DialogDescription>
                    Record a new financial transaction for your company
                  </DialogDescription>
                </DialogHeader>
                {/* <TransactionForm
                  companies={companies || []}
                  categories={categories || []}
                  onSubmit={(data) => createTransactionMutation.mutate(data)}
                  isSubmitting={createTransactionMutation.isPending}
                /> */}
              </DialogContent>
            </Dialog>

            <Button 
              variant="outline" 
              className="h-24 flex-col gap-2 border-2 hover:border-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-950/20"
              onClick={() => onNavigate("reports")}
            >
              <FileText className="h-6 w-6 text-emerald-600" />
              <span className="font-medium">View Reports</span>
            </Button>

            <Button 
              variant="outline" 
              className="h-24 flex-col gap-2 border-2 hover:border-violet-500 hover:bg-violet-50 dark:hover:bg-violet-950/20"
              onClick={() => onNavigate("companies")}
            >
              <TrendingUp className="h-6 w-6 text-violet-600" />
              <span className="font-medium">Company Analytics</span>
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card className="shadow-xl border-border/40">
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="text-2xl font-serif">Companies Performance Today</CardTitle>
          <Button variant="outline" onClick={() => onNavigate("companies")}>
            View Details
            <ArrowUpRight className="h-4 w-4 ml-2" />
          </Button>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
            {(companies || []).map((company) => (
              <CompanyCard company={company}
                // key={company.id}
                // name={company.name}
                // sector={company.industry}
                // cashBalance={company.cashBalance}
                // todayProfit={company.todayProfit}
                // revenue="—"
                // expenses="—"
                // status="active"
                // onClick={() => onNavigate(`company-${company.id}`)}
              />
            ))}
          </div>
        </CardContent>
      </Card>

      <Card className="shadow-xl border-border/40">
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="text-2xl font-serif">Recent Group Transactions</CardTitle>
          <Button variant="outline">View All</Button>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Date</TableHead>
                <TableHead>Company</TableHead>
                <TableHead>Description</TableHead>
                <TableHead>Type</TableHead>
                <TableHead className="text-right">Amount</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {(transactions || []).map((tx, index) => (
                <TableRow key={index} className="hover:bg-muted/50">
                  <TableCell className="font-medium">{tx.date}</TableCell>
                  <TableCell>{tx.company}</TableCell>
                  <TableCell>{tx.description}</TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={
                        tx.type === "income"
                          ? "bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-950/20 dark:text-emerald-400 dark:border-emerald-800"
                          : "bg-red-50 text-red-700 border-red-200 dark:bg-red-950/20 dark:text-red-400 dark:border-red-800"
                      }
                    >
                      {tx.type === "income" ? "Income" : "Expense"}
                    </Badge>
                  </TableCell>
                  <TableCell
                    className={`text-right font-serif font-semibold tabular-nums ${
                      tx.type === "income" ? "text-emerald-600 dark:text-emerald-400" : "text-red-600 dark:text-red-400"
                    }`}
                  >
                    {tx.amount}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  )
}

function TransactionForm({ 
  companies, 
  categories, 
  onSubmit, 
  isSubmitting 
}: { 
  companies: any[]
  categories: any[]
  onSubmit: (data: TransactionPayload) => void
  isSubmitting: boolean
}) {
  const [formData, setFormData] = useState<Partial<TransactionPayload>>({
    transactionType: "debit",
    paymentMethod: "cash",
    date: new Date().toISOString().split('T')[0],
  })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    
    if (!formData.companyId || !formData.amount || !formData.categoryId || !formData.description) {
      toast.error("Please fill in all required fields")
      return
    }

    onSubmit({
      ...formData,
      createdBy: 1, // Replace with actual user ID
    } as TransactionPayload)
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="company">Company *</Label>
          <Select 
            value={formData.companyId?.toString()} 
            onValueChange={(v) => setFormData({ ...formData, companyId: parseInt(v) })}
          >
            <SelectTrigger id="company">
              <SelectValue placeholder="Select company" />
            </SelectTrigger>
            <SelectContent>
              {companies.map((c) => (
                <SelectItem key={c.id} value={c.id.toString()}>{c.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div>
          <Label htmlFor="type">Type *</Label>
          <Select 
            value={formData.transactionType} 
            onValueChange={(v: any) => setFormData({ ...formData, transactionType: v })}
          >
            <SelectTrigger id="type">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="debit">Income (Money In)</SelectItem>
              <SelectItem value="credit">Expense (Money Out)</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="amount">Amount (RWF) *</Label>
          <Input 
            id="amount" 
            type="number" 
            placeholder="100000"
            value={formData.amount || ""}
            onChange={(e) => setFormData({ ...formData, amount: parseFloat(e.target.value) })}
          />
        </div>

        <div>
          <Label htmlFor="date">Date *</Label>
          <Input 
            id="date" 
            type="date"
            value={formData.date}
            onChange={(e) => setFormData({ ...formData, date: e.target.value })}
          />
        </div>
      </div>

      <div>
        <Label htmlFor="category">Category *</Label>
        <Select 
          value={formData.categoryId?.toString()} 
          onValueChange={(v) => setFormData({ ...formData, categoryId: parseInt(v) })}
        >
          <SelectTrigger id="category">
            <SelectValue placeholder="Select category" />
          </SelectTrigger>
          <SelectContent>
            {categories.map((c) => (
              <SelectItem key={c.id} value={c.id.toString()}>
                {c.name} ({c.code})
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div>
        <Label htmlFor="description">Description *</Label>
        <Textarea 
          id="description" 
          placeholder="Enter transaction description"
          value={formData.description || ""}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="paymentMethod">Payment Method</Label>
          <Select 
            value={formData.paymentMethod} 
            onValueChange={(v: any) => setFormData({ ...formData, paymentMethod: v })}
          >
            <SelectTrigger id="paymentMethod">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="cash">Cash</SelectItem>
              <SelectItem value="bank_transfer">Bank Transfer</SelectItem>
              <SelectItem value="mobile_money">Mobile Money</SelectItem>
              <SelectItem value="cheque">Cheque</SelectItem>
              <SelectItem value="credit_card">Credit Card</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div>
          <Label htmlFor="taxRate">Tax Rate (%)</Label>
          <Input 
            id="taxRate" 
            type="number" 
            placeholder="18"
            value={formData.taxRate || ""}
            onChange={(e) => setFormData({ ...formData, taxRate: parseFloat(e.target.value) })}
          />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="counterparty">Counterparty</Label>
          <Input 
            id="counterparty" 
            placeholder="Company or person name"
            value={formData.counterparty || ""}
            onChange={(e) => setFormData({ ...formData, counterparty: e.target.value })}
          />
        </div>

        <div>
          <Label htmlFor="invoiceNumber">Invoice Number</Label>
          <Input 
            id="invoiceNumber" 
            placeholder="INV-2024-001"
            value={formData.invoiceNumber || ""}
            onChange={(e) => setFormData({ ...formData, invoiceNumber: e.target.value })}
          />
        </div>
      </div>

      <div className="flex justify-end gap-3 pt-4">
        <Button type="button" variant="outline" onClick={() => setFormData({})}>
          Reset
        </Button>
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? "Creating..." : "Create Transaction"}
        </Button>
      </div>
    </form>
  )
}
